def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u, case-insensitive) in `text`.
    The letter y is not a vowel, except when it functions as one, i.e. when it
    is immediately followed by a consonant (as in "rhythms")."""
    count = 0
    n = len(text)
    for i, ch in enumerate(text):
        c = ch.lower()
        if c in "aeiou":
            count += 1
        elif c == "y" and i + 1 < n and text[i + 1].lower() not in "aeiouy":
            count += 1
    return count

